// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.nio.ByteBuffer;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Contract tests for physical source coordinates exported by LMDB record iterators. */
class LmdbRecordIteratorSourceCoordinateTest {

	@TempDir
	File dataDir;

	private TripleStore tripleStore;

	@BeforeEach
	void setUp() throws Exception {
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		tripleStore.startTransaction();
		for (long subject = 100; subject < 110; subject++) {
			tripleStore.storeTriple(subject, 10, 1000 + subject, 1, true);
		}
		tripleStore.commit();
	}

	@AfterEach
	void tearDown() throws Exception {
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	@Test
	void reopenedPinnedRelationMatchesButDifferentRelationsAndSnapshotsDecline() throws Exception {
		try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			Object identity;
			int identityHash;
			try (RecordIterator first = tripleStore.getTriples(txn, -1, 10, -1, -1, true)) {
				assertThat(first.hasSourceCoordinates()).isTrue();
				identity = first.copySourceCoordinateIdentity();
				identityHash = first.sourceCoordinateHash();
				assertThat(identity).isNotNull();
				assertThat(first.matchesSourceCoordinateIdentity(identity)).isTrue();
			}

			try (RecordIterator reopened = tripleStore.getTriples(txn, -1, 10, -1, -1, true)) {
				assertThat(reopened.matchesSourceCoordinateIdentity(identity)).isTrue();
				assertThat(reopened.sourceCoordinateHash()).isEqualTo(identityHash);
			}

			try (RecordIterator differentContext = tripleStore.getTriples(txn, -1, 10, -1, 1, true)) {
				assertThat(differentContext.matchesSourceCoordinateIdentity(identity)).isFalse();
			}

			try (RecordIterator differentIndex = tripleStore.getTriples(txn, 100, 10, -1, -1, true)) {
				assertThat(differentIndex.getIndexName()).isNotEqualTo("posc");
				assertThat(differentIndex.matchesSourceCoordinateIdentity(identity)).isFalse();
			}

			String indexName = tripleStore.getIndexName(-1, 10, -1, -1);
			LmdbKeyRange range = new LmdbKeyRange(poscKey(10, 1103, 0, 0), poscKey(10, 1107, 0, 0), indexName);
			try (RecordIterator bounded = tripleStore.getTriplesRange(txn, -1, 10, -1, -1, true, range)) {
				assertThat(bounded.matchesSourceCoordinateIdentity(identity)).isFalse();
			}

			try (RecordIterator differentPlane = tripleStore.getTriples(txn, -1, 10, -1, -1, false)) {
				assertThat(differentPlane.matchesSourceCoordinateIdentity(identity)).isFalse();
			}

			try (Txn anotherSnapshot = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision);
					RecordIterator independent = tripleStore.getTriples(anotherSnapshot, -1, 10, -1, -1, true)) {
				assertThat(independent.matchesSourceCoordinateIdentity(identity)).isFalse();
			}
		}
	}

	@Test
	void mixedNextAndFillKeepOneOrdinalAndSeekDisablesCoordinates() throws Exception {
		try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision);
				RecordIterator iterator = tripleStore.getTriples(txn, -1, 10, -1, -1, true)) {
			long[] rows = new long[4 * 2];
			long[] coordinates = new long[5 * 2];
			assertThat(iterator.fillWithSourceCoordinates(rows, coordinates, 2, 7L, 101L)).isEqualTo(2);
			assertCoordinate(coordinates, 0, 7L, 0L, 101L);
			assertCoordinate(coordinates, 1, 7L, 1L, 101L);

			long[] scalar = iterator.next();
			assertThat(scalar[TripleIndex.SUBJ_IDX]).isEqualTo(102L);
			assertThat(iterator.fillWithSourceCoordinates(rows, coordinates, 2, 7L, 101L)).isEqualTo(2);
			assertCoordinate(coordinates, 0, 7L, 3L, 101L);
			assertCoordinate(coordinates, 1, 7L, 4L, 101L);

			Object identity = iterator.copySourceCoordinateIdentity();
			assertThat(identity).isNotNull();
			assertThat(iterator.seekForward(0, 10, 1106, 0)).isTrue();
			assertThat(iterator.hasSourceCoordinates()).isFalse();
			assertThat(iterator.matchesSourceCoordinateIdentity(identity)).isFalse();
			assertThat(iterator.fillWithSourceCoordinates(rows, coordinates, 1, 7L, 101L)).isEqualTo(1);
			assertThat(rows[TripleIndex.SUBJ_IDX]).isEqualTo(106L);
			assertThat(coordinates[4]).isZero();
		}
	}

	@Test
	void unpinnedReadFillWritesUnavailableNamespace() throws Exception {
		try (Txn txn = tripleStore.getTxnManager().createReadTxn();
				RecordIterator iterator = tripleStore.getTriples(txn, -1, 10, -1, -1, true)) {
			assertThat(iterator.hasSourceCoordinates()).isFalse();

			long[] rows = new long[4];
			long[] coordinates = new long[5];
			assertThat(iterator.fillWithSourceCoordinates(rows, coordinates, 1, 7L, 101L)).isEqualTo(1);

			assertThat(rows[TripleIndex.SUBJ_IDX]).isEqualTo(100L);
			assertThat(coordinates[2]).isZero();
			assertThat(coordinates[4]).isZero();
		}
	}

	@Test
	void resumeAfterDeclinesCoordinatesWithoutRepeatingTheLastQuad() throws Exception {
		try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			long[] last;
			try (RecordIterator initial = tripleStore.getTriples(txn, -1, 10, -1, -1, true)) {
				last = initial.next().clone();
			}
			try (RecordIterator iterator = tripleStore.getTriples(txn, -1, 10, -1, -1, true)) {
				assertThat(iterator.hasSourceCoordinates()).isTrue();
				((LmdbRecordIterator) iterator).resumeAfter(last);
				assertThat(iterator.hasSourceCoordinates()).isFalse();

				long[] rows = new long[4];
				long[] coordinates = new long[5];
				assertThat(iterator.fillWithSourceCoordinates(rows, coordinates, 1, 9L, 103L)).isEqualTo(1);
				assertThat(rows[TripleIndex.SUBJ_IDX]).isEqualTo(101L);
				assertThat(coordinates[4]).isZero();
			}
		}
	}

	private static void assertCoordinate(long[] coordinates, int row, long group, long position, long namespace) {
		int at = row * 5;
		assertThat(coordinates[at]).isEqualTo(group);
		assertThat(coordinates[at + 1]).isZero();
		assertThat(coordinates[at + 2]).isEqualTo(position);
		assertThat(coordinates[at + 3]).isZero();
		assertThat(coordinates[at + 4]).isEqualTo(namespace);
	}

	private static byte[] poscKey(long predicate, long object, long subject, long context) {
		ByteBuffer buffer = ByteBuffer.allocate(TripleIndex.MAX_KEY_LENGTH);
		Varint.writeListUnsigned(buffer, new long[] { predicate, object, subject, context });
		buffer.flip();
		byte[] key = new byte[buffer.remaining()];
		buffer.get(key);
		return key;
	}
}
